package com.quicknotes.app;
import android.content.Context;import android.graphics.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.regex.*;
/** Fetch metadata and a bounded raster thumbnail, never execute website content. */
final class LinkPreview {
 static final Pattern TAG=Pattern.compile("<(meta|link|img)\\b[^>]*>",Pattern.CASE_INSENSITIVE);
 static final Pattern ATTR=Pattern.compile("([\\w:-]+)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))",Pattern.CASE_INSENSITIVE);
 static String decode(String s){return s.replace("&amp;","&").replace("&#38;","&").replace("&quot;","\"").replace("&#39;","'");}
 static String primary(String html,String base)throws Exception{String twitter="",link="",img="";Matcher tags=TAG.matcher(html);while(tags.find()){Map<String,String> attrs=new HashMap<>();Matcher a=ATTR.matcher(tags.group());while(a.find())attrs.put(a.group(1).toLowerCase(Locale.ROOT),decode(a.group(2)!=null?a.group(2):a.group(3)!=null?a.group(3):a.group(4)));String key=attrs.containsKey("property")?attrs.get("property"):attrs.get("name"),content=attrs.get("content");if("og:image".equalsIgnoreCase(key)&&content!=null)return new URL(new URL(base),content).toString();if("twitter:image".equalsIgnoreCase(key)&&content!=null)twitter=content;if("image_src".equalsIgnoreCase(attrs.get("rel")))link=attrs.getOrDefault("href","");if(img.isEmpty()&&tags.group(1).equalsIgnoreCase("img"))img=attrs.getOrDefault("src","");}String selected=!twitter.isEmpty()?twitter:!link.isEmpty()?link:img;return selected.isEmpty()?"":new URL(new URL(base),selected).toString();}
 static HttpURLConnection connection(String raw)throws Exception{URL u=new URL(raw);for(int n=0;n<5;n++){if(!u.getProtocol().equals("https")||u.getUserInfo()!=null)throw new IOException("HTTPS required");for(InetAddress addr:InetAddress.getAllByName(u.getHost()))if(addr.isAnyLocalAddress()||addr.isLoopbackAddress()||addr.isSiteLocalAddress()||addr.isLinkLocalAddress()||addr.isMulticastAddress())throw new IOException("Public website required");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(4000);c.setReadTimeout(4000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","QuickNotes/1.5 LinkPreview");int status=c.getResponseCode();if(status>=300&&status<400){String next=c.getHeaderField("Location");c.disconnect();u=new URL(u,next);continue;}if(status!=200){c.disconnect();throw new IOException("Preview unavailable");}return c;}throw new IOException("Too many redirects");}
 static byte[] download(HttpURLConnection c,int limit,boolean truncate)throws Exception{try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){if(total+n>limit){if(truncate){out.write(b,0,limit-total);break;}throw new IOException("Preview too large");}out.write(b,0,n);total+=n;}return out.toByteArray();}finally{c.disconnect();}}
 static synchronized File image(Context context,String raw)throws Exception{if(raw==null||raw.length()>4096)throw new IOException("Invalid URL");String key=java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(java.security.MessageDigest.getInstance("SHA-256").digest(raw.getBytes("UTF-8")));File dir=new File(context.getCacheDir(),"link-previews");dir.mkdirs();File file=new File(dir,key+".jpg"),miss=new File(dir,key+".miss");long now=System.currentTimeMillis();if(file.exists()&&now-file.lastModified()<7*86400000L)return file;if(miss.exists()&&now-miss.lastModified()<6*3600000L)throw new IOException("No preview");try{HttpURLConnection c=connection(raw);String base=c.getURL().toString(),type=c.getContentType();if(type==null||!type.toLowerCase(Locale.ROOT).contains("text/html")){c.disconnect();throw new IOException("Not HTML");}String image=primary(new String(download(c,512*1024,true),"UTF-8"),base);if(image.isEmpty())throw new IOException("No primary image");HttpURLConnection picture=connection(image);String mime=picture.getContentType();if(mime==null||!mime.startsWith("image/")||mime.contains("svg")){picture.disconnect();throw new IOException("Not a raster image");}byte[] data=download(picture,2*1024*1024,false);BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,options);if(options.outWidth<=0||options.outHeight<=0)throw new IOException("Invalid image");options.inSampleSize=1;while(options.outWidth/options.inSampleSize>640||options.outHeight/options.inSampleSize>640)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(data,0,data.length,options);if(bitmap==null)throw new IOException("Cannot decode image");try(FileOutputStream out=new FileOutputStream(file)){bitmap.compress(Bitmap.CompressFormat.JPEG,82,out);}finally{bitmap.recycle();}miss.delete();}catch(Exception e){try(FileOutputStream out=new FileOutputStream(miss)){out.write(0);}throw e;}finally{File[] files=dir.listFiles();if(files!=null&&files.length>100){Arrays.sort(files,Comparator.comparingLong(File::lastModified));for(int n=0;n<files.length-100;n++)files[n].delete();}}return file;}
}
